// Precise, actionable tool errors let the agent correct its own call on the next turn.
export function toolErrorGuidance(error:unknown){
 if(error instanceof z.ZodError){
  const issues=error.issues.slice(0,6).map(issue=>(issue.path.length?issue.path.join('.'):'(entrée)')+' : '+issue.message+('expected' in issue&&issue.expected?' (attendu : '+String(issue.expected)+')':'')+('keys' in issue&&Array.isArray(issue.keys)?' (champs en trop : '+issue.keys.join(', ')+')':''));
  return 'Paramètres d’outil invalides. Corrige uniquement ces points puis rappelle l’outil : '+issues.join(' ; ')+(error.issues.length>6?' ; …':'')+'.';
 }
 return 'Le service de cet outil n’a pas répondu. Réessaie une seule fois ; si l’échec persiste, dis-le simplement à l’utilisateur et continue avec ce qui est disponible.';
}
